// Build summary for email notification
const keywords = $input.first().json.saved_keywords || [];
const batchId = $('1. Define Seed Keywords').item.json.batch_id;

const total = keywords.length;
const topKeywords = keywords
  .slice(0, 10)
  .map((kw, i) => `${i + 1}. ${kw.keyword_text} (Score: ${kw.priority_score}, Vol: ${kw.volume}, KD: ${kw.kd})`)
  .join('\n');

const avgScore = total > 0 
  ? Math.round(keywords.reduce((sum, kw) => sum + kw.priority_score, 0) / total) 
  : 0;

const avgVolume = total > 0
  ? Math.round(keywords.reduce((sum, kw) => sum + kw.volume, 0) / total)
  : 0;

return [{
  json: {
    batch_id: batchId,
    total_keywords: total,
    avg_priority_score: avgScore,
    avg_volume: avgVolume,
    top_10_keywords: topKeywords,
    execution_date: new Date().toISOString()
  }
}];

